css:
.ap-art{position:relative;overflow:hidden}.ap-art svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.fx-rs{width:min(1060px,100%);display:grid;gap:1.6em}
.fx-rs .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}
.fx-rs h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-rs .top p{opacity:.6;font-size:.95em;max-width:32em}
.fx-rs .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.1em}
.fx-rs figure{margin:0;display:grid;gap:.6em}
.fx-rs figcaption{display:grid;gap:.1em}.fx-rs figcaption b{font:600 1em var(--font-heading)}.fx-rs figcaption span{font-size:.85em;opacity:.65}
.rs{position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;isolation:isolate;border:1px solid var(--border);background:var(--surface)}
.rs-base,.rs-l{position:absolute;inset:0}
.rs-base svg,.rs-l svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.rs-on{background:#000}.rs-on .rs-base{display:none}
.rs-l{mix-blend-mode:screen;will-change:transform}
.rs-r{filter:url(#rs-fr);transform:translate(calc(var(--vx,0)*-1px),calc(var(--vy,0)*-1px))}
.rs-g{filter:url(#rs-fg)}
.rs-b{filter:url(#rs-fb);transform:translate(calc(var(--vx,0)*1px),calc(var(--vy,0)*1px))}
.rs-defs{position:absolute;width:0;height:0;overflow:hidden}
@media(max-width:700px){.fx-rs .grid{grid-template-columns:repeat(2,minmax(0,1fr))}.fx-rs figure:last-child{grid-column:span 2}.fx-rs figure:last-child .rs{aspect-ratio:16/10}}

js:
(function(){
var tiles=[].slice.call(document.querySelectorAll('.fx-rs [data-rs]'));
if(!tiles.length||(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches))return;
function uid(s,n){return s.replace(/id="(ap-[a-z0-9]+)"/g,'id="$1-'+n+'"').replace(/url\(#(ap-[a-z0-9]+)\)/g,'url(#$1-'+n+')')}
var uidn=0;
tiles.forEach(function(t){var svg=t.querySelector('.rs-base').innerHTML;
 ['r','g','b'].forEach(function(c){var l=document.createElement('div');l.className='rs-l rs-'+c;l.setAttribute('aria-hidden','true');l.innerHTML=uid(svg,++uidn);t.appendChild(l)});
 t.classList.add('rs-on');t.__vx=0;
 t.addEventListener('pointermove',function(e){if(e.pointerType==='touch')return;var dx=e.movementX||0;t.__vx=Math.max(-22,Math.min(22,t.__vx+dx*.7));req()})});
var vy=0,last=window.scrollY,raf=0;
function cl(v,a){return v<-a?-a:v>a?a:v}
function tick(){raf=0;var y=window.scrollY;vy+=((y-last)*.9-vy)*.35;last=y;var busy=Math.abs(vy)>.05;if(!busy)vy=0;
 tiles.forEach(function(t){t.__vx*=.88;if(Math.abs(t.__vx)<.05)t.__vx=0;else busy=true;
  t.style.setProperty('--vy',cl(vy,26).toFixed(1));t.style.setProperty('--vx',t.__vx.toFixed(1))});
 if(busy)raf=requestAnimationFrame(tick)}
function req(){if(!raf)raf=requestAnimationFrame(tick)}
addEventListener('scroll',req,{passive:true});
})();
